    aboutMissionParagraph1: 'भारत का कृषि क्षेत्र 60 करोड़ से अधिक लोगों को रोजगार देता है, फिर भी गुणवत्ता वाले इनपुट्स और भरोसेमंद जानकारी तक पहुँच असमान है। कृषीदुकान स्थानीय कृषि रिटेलरों और उनके किसानों के लिए एकीकृत डिजिटल मार्केटप्लेस बनाकर इसे बदलता है।',
    aboutMissionParagraph2: 'हम सिर्फ़ शॉपिंग ऐप नहीं हैं। हम एक कृषि इंटेलिजेंस प्लेटफॉर्म हैं — किसानों को सही उत्पाद खोजने, उनकी संरचना समझने और भरोसेमंद दुकानों से खरीदने में मदद करते हैं।',
